/**
 * Changelog emission — derives reviews/changelog.json from .phase.ts files.
 *
 * Discovers all phases via `discoverPhases()`, groups done phases by version
 * into features/fixes/internal sections, and writes a single small JSON file
 * consumed by `scripts/generate-changelog-md.ts`.
 *
 * Usage:
 *   npx tsx <roadmap-root>/lib/emit.ts
 */

import { execSync } from 'node:child_process'
import fs from 'node:fs'
import path from 'node:path'
import { crossValidate, discoverArcs, discoverPhases, DUPLICATE_PHASE_NUMBER_PREFIX } from './registry'
import type { Phase } from './schema'

// ── Changelog computation ───────────────────────────────────────────────────

interface ChangelogVersion {
  version: string
  date: string
  sections: {
    features: { name: string; description: string }[]
    fixes: { name: string; description: string }[]
    internal: { name: string; description: string }[]
  }
}

function computeChangelog(phases: Phase[]): ChangelogVersion[] {
  // Group done phases by version
  const byVersion = new Map<string, Phase[]>()
  for (const p of phases) {
    if (p.status !== 'done' || !p.version) continue
    const existing = byVersion.get(p.version) ?? []
    existing.push(p)
    byVersion.set(p.version, existing)
  }

  // Sort versions descending (newest first)
  const versions = [...byVersion.keys()].sort((a, b) => {
    const [aMaj, aMin, aPat] = a.split('.').map(Number)
    const [bMaj, bMin, bPat] = b.split('.').map(Number)
    return bMaj - aMaj || bMin - aMin || (bPat ?? 0) - (aPat ?? 0)
  })

  return versions.map((version) => {
    const vPhases = byVersion.get(version) ?? []
    const features: { name: string; description: string }[] = []
    const fixes: { name: string; description: string }[] = []
    const internal: { name: string; description: string }[] = []

    for (const p of vPhases) {
      const entry = { name: p.name, description: p.stakeholderDemo }
      if (p.category === 'feature') features.push(entry)
      else if (p.category === 'fix') fixes.push(entry)
      else internal.push(entry)
    }

    // Find date: try phase completedDate first, fall back to git tag date
    const latestPhaseDate = vPhases
      .map((p) => p.completedDate)
      .filter(Boolean)
      .sort()
      .pop()

    let date = latestPhaseDate ?? ''
    if (!date) {
      try {
        const tagDate = execSync(`git log -1 --format=%ci v${version} 2>/dev/null`, {
          encoding: 'utf-8',
        }).trim()
        if (tagDate) date = tagDate.split(' ')[0] // YYYY-MM-DD
      } catch {
        // No git tag for this version
      }
    }

    return { version, date, sections: { features, fixes, internal } }
  })
}

// ── Main emission ───────────────────────────────────────────────────────────

const CHANGELOG_PATH = path.resolve(process.cwd(), 'reviews/changelog.json')

async function emit() {
  const { phases, errors } = await discoverPhases()

  // Duplicate phase numbers stay FATAL: silent tolerance causes
  // non-deterministic lookups-by-number, so any collision halts emission.
  // Every other discovery error (a sibling's parse/import failure) is
  // QUARANTINED — warned, excluded, emission proceeds — so one malformed file
  // can't block every session's phase completion.
  const duplicates = errors.filter((e) => e.error.startsWith(DUPLICATE_PHASE_NUMBER_PREFIX))
  const quarantined = errors.filter((e) => !e.error.startsWith(DUPLICATE_PHASE_NUMBER_PREFIX))

  if (duplicates.length > 0) {
    console.error('Discovery errors (duplicate numbers are fatal):')
    for (const e of duplicates) console.error(`  ${e.file}: ${e.error}`)
    process.exit(1)
  }
  if (quarantined.length > 0) {
    console.error('QUARANTINED (excluded from emission — fix these files):')
    for (const e of quarantined) console.error(`  ${e.file}: ${e.error}`)
  }

  // Arc ↔ phase integrity: emit is the early signal (warnings only);
  // audit-roadmap remains the enforcement surface.
  const { arcs, errors: arcErrors } = await discoverArcs()
  for (const e of arcErrors) console.error(`  arc warning — ${e.file}: ${e.error}`)
  for (const v of crossValidate(phases, arcs)) console.error(`  cross-validate warning — ${v}`)

  const changelog = computeChangelog(phases)
  const changelogJson = `${JSON.stringify({ versions: changelog }, null, 2)}\n`

  fs.mkdirSync(path.dirname(CHANGELOG_PATH), { recursive: true })
  fs.writeFileSync(CHANGELOG_PATH, changelogJson)

  console.log(`Changelog: ${CHANGELOG_PATH}`)
  console.log(`  ${phases.length} phases scanned, ${changelog.length} versions emitted`)
  if (quarantined.length > 0) {
    console.log(
      `  WARNING: ${quarantined.length} file(s) quarantined and NOT emitted: ${quarantined.map((e) => e.file).join(', ')}`,
    )
  }
}

emit().catch((err) => {
  console.error('Emission failed:', err)
  process.exit(1)
})
=====REG
/**
 * Phase & arc discovery — glob *.phase.ts / *.arc.ts files and dynamic-import them.
 *
 * Pattern: convention-based discovery via file pattern matching + dynamic
 * import + Zod validation. Scaffolded by roadmap-plugin scaffold-roadmap.sh.
 *
 * Duplicate phase numbers are reported as errors with BOTH colliding file
 * paths so the operator can bisect immediately. `crossValidate` is a pure
 * (I/O-free) check that the discovered phases and arcs reference each other
 * consistently.
 */

import fs from 'node:fs'
import path from 'node:path'
import {
  ArcInputShape,
  normalizeArc,
  type Arc,
  type Phase,
  type PhaseExecutionResult,
} from './schema'

/** Shared discriminant for the one FATAL discovery error class. emit.ts filters
 *  on this exact prefix to keep duplicates exit-1 while quarantining parse
 *  failures — a shared constant so the wording cannot drift into a silent
 *  fatal→warning downgrade. */
export const DUPLICATE_PHASE_NUMBER_PREFIX = 'Duplicate phase number'

/**
 * The consumer's roadmap root, discovered — the ONE file that cannot import the plugin's
 * cli/lib/roadmap-root.mjs (this is consumer-side scaffolded code), so its three rules are
 * restated here and nowhere else: ROADMAP_ROOT wins; else the first candidate carrying a
 * phases/ directory; else the default. Keep in step with ROOT_CANDIDATES in the plugin.
 */
const ROADMAP_ROOT_CANDIDATES = ['roadmap', 'docs/roadmap']

export function roadmapRoot(cwd: string = process.cwd()): string {
  const override = process.env.ROADMAP_ROOT
  if (override) return path.isAbsolute(override) ? override : path.resolve(cwd, override)
  const marked = ROADMAP_ROOT_CANDIDATES.filter((c) => fs.existsSync(path.resolve(cwd, c, 'phases')))
  return path.resolve(cwd, marked[0] ?? ROADMAP_ROOT_CANDIDATES[0])
}

export interface DiscoveryResult {
  phases: Phase[]
  errors: { file: string; error: string }[]
}

export interface ArcDiscoveryResult {
  arcs: Arc[]
  errors: { file: string; error: string }[]
}

export interface ResultDiscoveryResult {
  results: PhaseExecutionResult[]
  errors: { file: string; error: string }[]
}

/**
 * Discover all .phase.ts files, import them, and return validated Phase objects.
 * Each file must `export default definePhase({...})`.
 */
export async function discoverPhases(
  rootDir: string = path.join(roadmapRoot(), 'phases'),
): Promise<DiscoveryResult> {
  const files = fs
    .readdirSync(rootDir)
    .filter((f) => f.endsWith('.phase.ts'))
    .sort()
    .map((f) => path.join(rootDir, f))

  // Track (phase, file) tuples so duplicate detection can surface both paths
  const phasesWithFiles: { phase: Phase; file: string }[] = []
  const errors: { file: string; error: string }[] = []

  for (const file of files) {
    try {
      const mod = await import(file)
      const phase = mod.default as Phase
      if (!phase || typeof phase.phase !== 'number') {
        errors.push({ file, error: 'No valid default export (must use definePhase())' })
        continue
      }
      phasesWithFiles.push({ phase, file })
    } catch (err) {
      errors.push({
        file,
        error: err instanceof Error ? err.message : String(err),
      })
    }
  }

  // Detect duplicate phase numbers — report ALL colliding file paths per number
  const byNumber = new Map<number, string[]>()
  for (const { phase, file } of phasesWithFiles) {
    const existing = byNumber.get(phase.phase) ?? []
    existing.push(file)
    byNumber.set(phase.phase, existing)
  }

  for (const [num, filePaths] of byNumber) {
    if (filePaths.length > 1) {
      errors.push({
        file: filePaths.join(', '),
        error: `${DUPLICATE_PHASE_NUMBER_PREFIX} ${num} in ${filePaths.length} files: ${filePaths.join(' and ')}`,
      })
    }
  }

  // Sort by phase number for stable output
  const phases = phasesWithFiles.map((p) => p.phase).sort((a, b) => a.phase - b.phase)

  return { phases, errors }
}

/**
 * Re-read the persisted `PhaseExecutionResult` roll-ups from the phase files.
 *
 * `do-arc` accumulates these in-context as it runs an arc, but that array is
 * ordinary conversation state — lost if the run is resumed or its context
 * compacts (exactly the long-arc case recursion mode targets). do-phase arc-mode
 * persists each phase's roll-up to `phase.executionResult`, so `arc-sweep` can
 * reconstruct the set durably instead of depending on the in-context hand-off.
 * Reuses `discoverPhases` so discovery/validation lives in one place.
 */
export async function discoverResults(
  rootDir: string = path.join(roadmapRoot(), 'phases'),
): Promise<ResultDiscoveryResult> {
  const { phases, errors } = await discoverPhases(rootDir)
  const results = phases
    .map((p) => p.executionResult)
    .filter((r): r is PhaseExecutionResult => r != null)
  return { results, errors }
}

/**
 * Discover all .arc.ts files, import them, and return validated Arc objects.
 * Each file must `export default defineArc({...})`.
 *
 * Unlike discoverPhases (which relies on definePhase parsing at import time), an
 * .arc.ts file could export a raw object literal, so the registry parses
 * defensively with `ArcInputShape` (accepting both the `planes` and flat `phases`
 * forms) and normalizes the result, routing failures into `errors`. A missing
 * `export default` is reported with the same clarity as the phase path. Duplicate
 * arc ids across files are reported with BOTH colliding paths (mirroring the
 * duplicate-phase-number check). A missing roadmap/arcs directory is not an error
 * — arcs are optional.
 */
export async function discoverArcs(
  rootDir: string = path.join(roadmapRoot(), 'arcs'),
): Promise<ArcDiscoveryResult> {
  if (!fs.existsSync(rootDir)) {
    return { arcs: [], errors: [] }
  }

  const files = fs
    .readdirSync(rootDir)
    .filter((f) => f.endsWith('.arc.ts'))
    .sort()
    .map((f) => path.join(rootDir, f))

  const arcsWithFiles: { arc: Arc; file: string }[] = []
  const errors: { file: string; error: string }[] = []

  for (const file of files) {
    try {
      const mod = await import(file)
      if (mod.default == null) {
        errors.push({ file, error: 'No valid default export (must use defineArc())' })
        continue
      }
      const parsed = ArcInputShape.safeParse(mod.default)
      if (!parsed.success) {
        errors.push({ file, error: parsed.error.message })
        continue
      }
      arcsWithFiles.push({ arc: normalizeArc(parsed.data), file })
    } catch (err) {
      errors.push({
        file,
        error: err instanceof Error ? err.message : String(err),
      })
    }
  }

  // Detect duplicate arc ids — report ALL colliding file paths per id. `id` is
  // `number | string`; key by its string form so `1` and `'1'` (ambiguous to
  // do-arc's CLI id resolution) are caught as a collision too.
  const byId = new Map<string, string[]>()
  for (const { arc, file } of arcsWithFiles) {
    const key = String(arc.id)
    const existing = byId.get(key) ?? []
    existing.push(file)
    byId.set(key, existing)
  }

  for (const [id, filePaths] of byId) {
    if (filePaths.length > 1) {
      errors.push({
        file: filePaths.join(', '),
        error: `Duplicate arc id ${id} in ${filePaths.length} files: ${filePaths.join(' and ')}`,
      })
    }
  }

  const arcs = arcsWithFiles.map((a) => a.arc)
  return { arcs, errors }
}

/**
 * Pure cross-check (no I/O) between discovered phases and arcs. Membership is
 * expressed twice — forward via `arc.planes[].phases`, back via `phase.arcId` —
 * and this guards every way the two can disagree. Returns one error string per
 * inconsistency:
 *  1. a phase whose `arcId` is set but matches no discovered arc id;
 *  2. an arc plane referencing a phase number no discovered phase defines;
 *  3. a phase claimed by more than one arc plane (two arcs, or twice within one
 *     arc) — a phase belongs to exactly one plane;
 *  4. a phase whose `arcId` names an arc that does NOT list it in its planes
 *     (the back-reference and the forward list disagree).
 *
 * Pure so the schema harness can exercise it directly without fixture files.
 */
export function crossValidate(phases: Phase[], arcs: Arc[]): string[] {
  const errors: string[] = []
  const arcIds = new Set<number | string>(arcs.map((a) => a.id))

  // (1) dangling arcId
  for (const phase of phases) {
    if (phase.arcId != null && !arcIds.has(phase.arcId)) {
      errors.push(`Phase ${phase.phase} declares arcId ${phase.arcId} but no arc has that id`)
    }
  }

  // (2) dangling plane phase + build the phase -> owning-arc-ids index
  const phaseNumbers = new Set(phases.map((p) => p.phase))
  const owners = new Map<number, (number | string)[]>()
  for (const arc of arcs) {
    for (const plane of arc.planes) {
      for (const num of plane.phases) {
        if (!phaseNumbers.has(num)) {
          errors.push(
            `Arc ${arc.id} plane "${plane.name}" references phase ${num} but no such phase exists`,
          )
        }
        const list = owners.get(num) ?? []
        list.push(arc.id)
        owners.set(num, list)
      }
    }
  }

  // (3) a phase claimed by more than one plane slot
  for (const [num, ownerIds] of owners) {
    if (ownerIds.length > 1) {
      errors.push(
        `Phase ${num} is claimed by ${ownerIds.length} arc planes (${ownerIds.join(', ')}) — a phase belongs to exactly one arc plane`,
      )
    }
  }

  // (4) arcId must name the arc whose planes actually list the phase (skip when
  // arcId is dangling — (1) already reports that, no need to double-flag)
  for (const phase of phases) {
    if (phase.arcId == null || !arcIds.has(phase.arcId)) continue
    const ownerIds = owners.get(phase.phase) ?? []
    if (!ownerIds.includes(phase.arcId)) {
      errors.push(
        `Phase ${phase.phase} declares arcId ${phase.arcId} but that arc's planes do not list it`,
      )
    }
  }

  return errors
}
=====BACKLOG
/**
 * Ordered execution backlog — first entry is next to execute.
 *
 * This file is the single source of truth for execution order.
 * Phase files own status and content; this file owns sequence.
 *
 * Grooming is automatic across the phase lifecycle:
 * - plan-phase does NOT edit this file directly.
 * - review-phase Mode A queues a phase ONLY when the verdict is READY
 *   (no findings, no unresolved [NEEDS CLARIFICATION] markers), at a
 *   position reasoned from priority + dependsOn + conflictsWith.
 * - do-phase reads index 0 when the user says "do next phase".
 * - do-phase Step 5 removes the phase entry when status flips to 'done',
 *   in the same commit that records completion.
 * - audit-roadmap flags stale entries (done phases still listed here).
 *
 * Manual edits remain valid — re-running review-phase on a queued phase
 * validates the position against the rules and proposes a move if
 * incorrect.
 *
 * Duplicate phase numbers are rejected at runtime by Zod.
 *
 * **Queue-only file.** One line per phase entry. No track narratives, no
 * "shipped on" notes, no completed-work summaries, no refresh-date prose.
 * Those belong elsewhere: commit history (git log), the phase file's
 * `compromises` + `gateRounds` fields, `reviews/changelog.json`, or a
 * curated CHANGELOG.md. The backlog answers one question — "what's next?"
 * — and accreted narrative makes that question harder to answer.
 *
 * Two input forms are supported (schema v5+):
 *   1. Flat array — `defineBacklog([{ phase: 1, name: '...' }])`
 *   2. Tiered     — `defineBacklog({ tiers: [{ tier: 0, label: '...', items: [...] }] })`
 *
 * To switch from flat to tiered, replace the array argument with a
 * `{ tiers: [...] }` object — the rest of the lifecycle is unchanged.
 * The flat form is normalized into a single `tier: 0` tier on parse, so
 * downstream code only ever sees the tiered shape.
 *
 * Pattern: zeroh2 golden shapes (heuristic — ZeroH-originated construct).
 */

import { defineBacklog } from './lib/schema'

export default defineBacklog([
  // Flat form (back-compat):
  // { phase: 1, name: 'Example phase name' },
  //
  // Or tiered form — comment-out the array and uncomment the block below:
  // {
  //   tiers: [
  //     {
  //       tier: 0,
  //       label: 'Sentinel becomes daily driver',
  //       items: [
  //         { phase: 1, name: 'Example phase name' },
  //       ],
  //     },
  //   ],
  // }
])
=====ROADMAP
# Roadmap

The installed roadmap CLI discovers the canonical roadmap root. This directory
contains `phases/`, `backlog.ts`, and the shared `lib/schema.ts`; phase files use
`definePhase()` from that schema. Do not create a second root or configuration.

## Phase execution

Use `/do-phase N` to execute a planned phase. The installed do-phase workflow owns
task sequencing, commits, reviews, and completion; this document is a pointer to
that workflow, not a separate execution procedure.

## Validation

Use `roadmap gate plan N` to inspect the required gate and `roadmap gate run N` to
execute its mechanical checks. The discovered `roadmap.config.json` supplies
`gateCommands`. Missing or invalid bindings require correction; never infer them
from harness prose or a package manager.

After recording the phase's completion evidence, run
`roadmap gate run N --verify-complete` to verify consistency. Consult `roadmap --help`
and the installed workflow for command details and the current review protocol.

## Integration

The discovered configuration's `mergePolicy` controls integration, landing, and
push behavior. When `mergePolicy` is absent, hold integration and push for the user.
The existence of a phase or a successful gate does not select a branch or remote.
